const __aivicBundle_3_generateMonthlyReportWithDetails = (() => {
  function generateMonthlyReportWithDetails(
    targetMonth: string,
    salesData: Array<{
      dealId: string;
      customerId: string;
      customerName: string;
      salesAmount: number;
      dealStatus: string;
      invoiceIssuedDate: string | null;
    }>
  ): MonthlySalesReport {
    const reportId = randomUUID();
    const generatedDate = new Date().toISOString();
  
    const closedDeals = salesData.filter((deal) => deal.dealStatus === "受注");
  
    const totalSales = closedDeals.reduce(
      (sum, deal) => sum + deal.salesAmount,
      0
    );
  
    const dealCount = closedDeals.length;
  
    const progressRate =
      salesData.length > 0
        ? (dealCount / salesData.length) * 100
        : 0;
  
    const customerMap = new Map<
      string,
      {
        customerId: string;
        customerName: string;
        totalSales: number;
        dealCount: number;
        allDealsCount: number;
      }
    >();
  
    for (const deal of salesData) {
      const key = deal.customerId;
      if (!customerMap.has(key)) {
        customerMap.set(key, {
          customerId: deal.customerId,
          customerName: deal.customerName,
          totalSales: 0,
          dealCount: 0,
          allDealsCount: 0,
        });
      }
      const customer = customerMap.get(key)!;
      customer.allDealsCount += 1;
      if (deal.dealStatus === "受注") {
        customer.totalSales += deal.salesAmount;
        customer.dealCount += 1;
      }
    }
  
    const customerDetails = Array.from(customerMap.values()).map((customer) => ({
      customerId: customer.customerId,
      customerName: customer.customerName,
      totalSales: customer.totalSales,
      dealCount: customer.dealCount,
      progressRate:
        customer.allDealsCount > 0
          ? (customer.dealCount / customer.allDealsCount) * 100
          : 0,
    }));
  
    return {
      reportId,
      month: targetMonth,
      generatedDate,
      totalSales,
      dealCount,
      progressRate,
      customerDetails,
      format: {
        currencyUnit: "JPY",
        decimalPlaces: 0,
        dateFormat: "YYYY-MM-DD",
      },
    };
  }
  return { generateMonthlyReportWithDetails };
})();
