/* AIVIC_FUNCTION_BUNDLE_START owner=detectDelayedInvoiceCase exports=detectDelayedInvoiceCase */
const __aivicBundle_8_detectDelayedInvoiceCase = (() => {
  interface DetectDelayedInvoiceCaseInput {
    deal_id: string;
    customer_id: string;
    deal_status: string;
    deal_status_update_date: Date;
    invoice_issue_date: Date;
    invoice_amount: number;
    days_threshold: number;
  }
  
  interface DetectDelayedInvoiceCaseOutput {
    is_delayed: boolean;
    days_difference: number;
    delay_reason: string;
    detection_status: string;
    alert_flag: boolean;
  }
  
   function detectDelayedInvoiceCase(
    input: DetectDelayedInvoiceCaseInput
  ): DetectDelayedInvoiceCaseOutput {
    if (!input.deal_status_update_date) {
      throw new Error("商談ステータス更新日が必要です");
    }
  
    if (!input.invoice_issue_date) {
      throw new Error("請求書発行日が必要です");
    }
  
    if (input.days_threshold < 0) {
      throw new Error("閾値は0以上である必要があります");
    }
  
    const updateDate = new Date(input.deal_status_update_date);
    const issueDate = new Date(input.invoice_issue_date);
  
    const timeDiffMs = issueDate.getTime() - updateDate.getTime();
    const daysDifference = Math.ceil(timeDiffMs / (1000 * 60 * 60 * 24));
  
    const isDelayed = daysDifference > input.days_threshold;
    const delayReason = isDelayed ? "請求書発行の遅延" : "";
    const detectionStatus = isDelayed ? "遅延案件" : "正常";
    const alertFlag = isDelayed;
  
    return {
      is_delayed: isDelayed,
      days_difference: daysDifference,
      delay_reason: delayReason,
      detection_status: detectionStatus,
      alert_flag: alertFlag,
    };
  }
  return { detectDelayedInvoiceCase };
})();
export const detectDelayedInvoiceCase = __aivicBundle_8_detectDelayedInvoiceCase.detectDelayedInvoiceCase;
/* AIVIC_FUNCTION_BUNDLE_END owner=detectDelayedInvoiceCase */

/* AIVIC_FUNCTION_BUNDLE_START owner=reconcileSalesAndBillingData exports=reconcileSalesAndBillingData */
const __aivicBundle_9_reconcileSalesAndBillingData = (() => {
  async function reconcileSalesAndBillingData(input: {
    customerId: string;
    portalUserId: string;
    reconciliationDate: Date;
  }): Promise<{
    success: boolean;
    errorCode?: string;
    errorMessage?: string;
    statusCode: number;
    dealDataExists: boolean;
    billingDataExists: boolean;
    reconciliationDetails: any;
    errorLogRecorded: boolean;
    errorLogId?: string;
    timestamp: string;
  }> {
    const timestamp = new Date().toISOString();
  
    try {
      // Fetch deal data
      const dealResponse = await fetch(
        `/api/deals?customerId=${encodeURIComponent(input.customerId)}`
      );
      const dealData = await dealResponse.json();
      const dealDataExists = dealResponse.status === 200 && dealData.data !== null;
  
      // Fetch billing data
      const billingResponse = await fetch(
        `/api/billing?customerId=${encodeURIComponent(input.customerId)}`
      );
      const billingData = await billingResponse.json();
      const billingDataExists =
        billingResponse.status === 200 && billingData.data !== null;
  
      // Both data sources missing
      if (!dealDataExists && !billingDataExists) {
        // Record error log
        const errorLogResponse = await fetch(`/api/error-logs`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            customerId: input.customerId,
            portalUserId: input.portalUserId,
            errorCode: "NO_DATA_TO_RECONCILE",
            errorMessage: "照合対象となるデータが見つかりません",
            reconciliationDate: input.reconciliationDate.toISOString(),
            timestamp: timestamp,
          }),
        });
        const errorLogResult = await errorLogResponse.json();
  
        return {
          success: false,
          errorCode: "NO_DATA_TO_RECONCILE",
          errorMessage: "照合対象となるデータが見つかりません",
          statusCode: 404,
          dealDataExists: false,
          billingDataExists: false,
          reconciliationDetails: null,
          errorLogRecorded: errorLogResult.recorded === true,
          errorLogId: errorLogResult.logId,
          timestamp: timestamp,
        };
      }
  
      // Both data sources exist - perform reconciliation
      const reconciliationDetails = {
        totalRevenueRecognized: dealDataExists ? dealData.data.totalAmount : 0,
        totalInvoiced: billingDataExists ? billingData.data.totalAmount : 0,
        totalUnbilled: dealDataExists
          ? dealData.data.unbilledAmount || 0
          : 0,
        unbilledDeals: dealDataExists ? dealData.data.unbilledDeals || [] : [],
        delayedDeals: billingDataExists ? billingData.data.delayedDeals || [] : [],
        reconciliationStatus: "COMPLETED",
      };
  
      return {
        success: true,
        statusCode: 200,
        dealDataExists: dealDataExists,
        billingDataExists: billingDataExists,
        reconciliationDetails: reconciliationDetails,
        errorLogRecorded: false,
        timestamp: timestamp,
      };
    } catch (error) {
      const errorLogResponse = await fetch(`/api/error-logs`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          customerId: input.customerId,
          portalUserId: input.portalUserId,
          errorCode: "RECONCILIATION_FAILED",
          errorMessage:
            error instanceof Error
              ? error.message
              : "照合処理中にエラーが発生しました",
          reconciliationDate: input.reconciliationDate.toISOString(),
          timestamp: timestamp,
        }),
      });
      const errorLogResult = await errorLogResponse.json();
  
      return {
        success: false,
        errorCode: "RECONCILIATION_FAILED",
        errorMessage:
          error instanceof Error
            ? error.message
            : "照合処理中にエラーが発生しました",
        statusCode: 500,
        dealDataExists: false,
        billingDataExists: false,
        reconciliationDetails: null,
        errorLogRecorded: errorLogResult.recorded === true,
        errorLogId: errorLogResult.logId,
        timestamp: timestamp,
      };
    }
  }
  return { reconcileSalesAndBillingData };
})();
