/* AIVIC_FUNCTION_BUNDLE_END owner=reconcileSalesAndBillingData */

/* AIVIC_FUNCTION_BUNDLE_START owner=matchDealReconciliation exports=matchDealReconciliation */
const __aivicBundle_10_matchDealReconciliation = (() => {
  function matchDealReconciliation(input: {
    dealId: string;
    dealStatus: string;
    dealStatusUpdateDate: Date;
    invoiceIssuedDate: Date;
    dealAmount: number;
    invoiceAmount: number;
    dealLineCount: number;
    invoiceLineCount: number;
  }): {
    reconciliationStatus: string;
    isSameDayIssue: boolean;
    amountMatch: boolean;
    lineCountMatch: boolean;
    errorMessage: null | string;
    isDiscrepancy: boolean;
    dealId: string;
    daysOffset: number;
  } {
    if (input["dealStatus"] === undefined || input["dealStatus"] === null) { throw new Error("dealStatus is required"); }
    const dealDate = new Date(input.dealStatusUpdateDate);
    const invoiceDate = new Date(input.invoiceIssuedDate);
  
    dealDate.setUTCHours(0, 0, 0, 0);
    invoiceDate.setUTCHours(0, 0, 0, 0);
  
    const isSameDayIssue = dealDate.getTime() === invoiceDate.getTime();
  
    const daysOffset = Math.floor(
      (invoiceDate.getTime() - dealDate.getTime()) / (1000 * 60 * 60 * 24)
    );
  
    const amountMatch = input.dealAmount === input.invoiceAmount;
    const lineCountMatch = input.dealLineCount === input.invoiceLineCount;
  
    const hasDiscrepancy =
      !isSameDayIssue || !amountMatch || !lineCountMatch;
  
    const reconciliationStatus =
      !hasDiscrepancy && isSameDayIssue && amountMatch && lineCountMatch
        ? "completed"
        : "pending";
  
    const errorMessage =
      !amountMatch || !lineCountMatch
        ? "Amount or line count mismatch detected"
        : null;
  
    return {
      reconciliationStatus,
      isSameDayIssue,
      amountMatch,
      lineCountMatch,
      errorMessage,
      isDiscrepancy: hasDiscrepancy,
      dealId: input.dealId,
      daysOffset,
    };
  }
  return { matchDealReconciliation };
})();
export const matchDealReconciliation = __aivicBundle_10_matchDealReconciliation.matchDealReconciliation;
