/* AIVIC_FUNCTION_BUNDLE_START owner=validateReportDataAccuracy exports=validateReportDataAccuracy */
const __aivicBundle_11_validateReportDataAccuracy = (() => {
  function validateReportDataAccuracy(
    sourceSystemData: {
      total_sales: number;
      deal_count: number;
      progress_rate: number;
      customer_deals: Array<{
        customer_id: string;
        customer_name: string;
        deals: Array<{
          deal_id: string;
          status: string;
          amount: number;
        }>;
      }>;
    },
    portalReportData: {
      total_sales: number;
      deal_count: number;
      progress_rate: number;
      customer_deals: Array<{
        customer_id: string;
        customer_name: string;
        deals: Array<{
          deal_id: string;
          status: string;
          amount: number;
        }>;
      }>;
    }
  ): {
    sales_match: boolean;
    deal_count_match: boolean;
    progress_rate_match: boolean;
    customer_deals_match: boolean;
    all_data_consistent: boolean;
    validation_status: string;
  } {
    const salesMatch = sourceSystemData.total_sales === portalReportData.total_sales;
    const dealCountMatch = sourceSystemData.deal_count === portalReportData.deal_count;
    const progressRateMatch = sourceSystemData.progress_rate === portalReportData.progress_rate;
  
    const customerDealsMatch = validateCustomerDealsMatch(
      sourceSystemData.customer_deals,
      portalReportData.customer_deals
    );
  
    const allDataConsistent = salesMatch && dealCountMatch && progressRateMatch && customerDealsMatch;
    const validationStatus = allDataConsistent ? "PASS" : "FAIL";
  
    return {
      sales_match: salesMatch,
      deal_count_match: dealCountMatch,
      progress_rate_match: progressRateMatch,
      customer_deals_match: customerDealsMatch,
      all_data_consistent: allDataConsistent,
      validation_status: validationStatus,
    };
  }
  
  function validateCustomerDealsMatch(
    sourceCustomerDeals: Array<{
      customer_id: string;
      customer_name: string;
      deals: Array<{
        deal_id: string;
        status: string;
        amount: number;
      }>;
    }>,
    portalCustomerDeals: Array<{
      customer_id: string;
      customer_name: string;
      deals: Array<{
        deal_id: string;
        status: string;
        amount: number;
      }>;
    }>
  ): boolean {
    if (sourceCustomerDeals.length !== portalCustomerDeals.length) {
      return false;
    }
  
    for (let i = 0; i < sourceCustomerDeals.length; i++) {
      const sourceCustomer = sourceCustomerDeals[i];
      const portalCustomer = portalCustomerDeals[i];
  
      if (
        sourceCustomer.customer_id !== portalCustomer.customer_id ||
        sourceCustomer.customer_name !== portalCustomer.customer_name
      ) {
        return false;
      }
  
      if (sourceCustomer.deals.length !== portalCustomer.deals.length) {
        return false;
      }
  
      for (let j = 0; j < sourceCustomer.deals.length; j++) {
        const sourceDeal = sourceCustomer.deals[j];
        const portalDeal = portalCustomer.deals[j];
  
        if (
          sourceDeal.deal_id !== portalDeal.deal_id ||
          sourceDeal.status !== portalDeal.status ||
          sourceDeal.amount !== portalDeal.amount
        ) {
          return false;
        }
      }
    }
  
    return true;
  }
  return { validateReportDataAccuracy };
})();
export const validateReportDataAccuracy = __aivicBundle_11_validateReportDataAccuracy.validateReportDataAccuracy;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateReportDataAccuracy */

/* AIVIC_FUNCTION_BUNDLE_START owner=validateReportData exports=validateReportData */
const __aivicBundle_12_validateReportData = (() => {
  function validateReportData(
    sourceReportData: any,
    reportDataToValidate?: any
  ): {
    isValid?: boolean;
    status?: string;
    discrepancyDetected?: boolean;
    discrepancyDetails?: {
      revenueDifference: number;
      direction: string;
      sourceValue: number;
      reportValue: number;
    };
    message?: string;
    sales_match?: boolean;
    deal_count_match?: boolean;
    progress_rate_match?: boolean;
    customer_deals_match?: boolean;
    all_data_consistent?: boolean;
    validation_status?: string;
    is_valid?: boolean;
    progress_rate_difference?: number;
    within_tolerance?: boolean;
    tolerance_threshold?: number;
    error_message?: string | null;
    validated_at?: string;
    recordCountMismatch?: boolean;
    sourceRecordCount?: number;
    reportRecordCount?: number;
    errorMessage?: string;
  } {
    const TOLERANCE_THRESHOLD = 0.01;
  
    // Case 1: sourceRecords and reportRecords arrays (record count mismatch detection)
    if (
      sourceReportData &&
      typeof sourceReportData === "object" &&
      "sourceRecords" in sourceReportData &&
      "reportRecords" in sourceReportData
    ) {
      const sourceRecords = sourceReportData.sourceRecords || [];
      const reportRecords = sourceReportData.reportRecords || [];
      const sourceCount = Array.isArray(sourceRecords) ? sourceRecords.length : 0;
      const reportCount = Array.isArray(reportRecords) ? reportRecords.length : 0;
  
      if (sourceCount !== reportCount) {
        return {
          isValid: false,
          recordCountMismatch: true,
          sourceRecordCount: sourceCount,
          reportRecordCount: reportCount,
          errorMessage: `件数が一致しません。元データ: ${sourceCount}件、報告書: ${reportCount}件`,
        };
      }
  
      return {
        isValid: true,
        recordCountMismatch: false,
        sourceRecordCount: sourceCount,
        reportRecordCount: reportCount,
      };
    }
  
    // Case 2: Two separate objects with revenue/totalRevenue comparison
    if (reportDataToValidate !== undefined) {
      const sourceRevenue =
        sourceReportData?.totalRevenue ?? sourceReportData?.revenue ?? 0;
      const reportRevenue =
        reportDataToValidate?.totalRevenue ?? reportDataToValidate?.revenue ?? 0;
      const revenueDifference = sourceRevenue - reportRevenue;
  
      if (revenueDifference !== 0) {
        return {
          isValid: false,
          status: "error",
          discrepancyDetected: true,
          discrepancyDetails: {
            revenueDifference,
            direction: revenueDifference < 0 ? "shortage" : "excess",
            sourceValue: sourceRevenue,
            reportValue: reportRevenue,
          },
          message: `売上に差異があります。差分: ${Math.abs(revenueDifference)}円`,
        };
      }
  
      // Check progress rate difference
      const sourceProgressRate =
        sourceReportData?.progress_rate ?? sourceReportData?.progressRate ?? 0;
      const reportProgressRate =
        reportDataToValidate?.progress_rate ??
        reportDataToValidate?.progressRate ??
        0;
      const progressRateDifference = Math.abs(
        sourceProgressRate - reportProgressRate
      );
      const withinTolerance = progressRateDifference <= TOLERANCE_THRESHOLD;
  
      return {
        status: "completed",
        is_valid: true,
        progress_rate_difference: parseFloat(progressRateDifference.toFixed(2)),
        within_tolerance: withinTolerance,
        tolerance_threshold: TOLERANCE_THRESHOLD,
        error_message: null,
        validated_at: new Date().toISOString(),
      };
    }
  
    // Case 3: Single object validation (fallback)
    return {
      isValid: true,
      status: "completed",
      discrepancyDetected: false,
      error_message: null,
      validated_at: new Date().toISOString(),
    };
  }
  return { validateReportData };
})();
export const validateReportData = __aivicBundle_12_validateReportData.validateReportData;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateReportData */

/* AIVIC_FUNCTION_BUNDLE_START owner=markUnbilledDeals exports=markUnbilledDeals */
const __aivicBundle_13_markUnbilledDeals = (() => {
  function markUnbilledDeals(
    input_deals: Array<{
      deal_id: string;
      deal_status: string;
      billing_scheduled_date: string;
      is_unbilled: boolean;
    }>,
    current_date: string
  ): Array<{
    deal_id: string;
    deal_status: string;
    billing_scheduled_date: string;
    is_unbilled: boolean;
  }> {
    return input_deals.map((deal) => {
      const shouldMarkUnbilled =
        deal.deal_status === '受注' &&
        deal.billing_scheduled_date <= current_date &&
        !deal.is_unbilled;
  
      return {
        deal_id: deal.deal_id,
        deal_status: deal.deal_status,
        billing_scheduled_date: deal.billing_scheduled_date,
        is_unbilled: shouldMarkUnbilled ? true : deal.is_unbilled,
      };
    });
  }
  return { markUnbilledDeals };
})();
export const markUnbilledDeals = __aivicBundle_13_markUnbilledDeals.markUnbilledDeals;
