/* AIVIC_FUNCTION_BUNDLE_START owner=determineDealUnbilledFlag exports=determineDealUnbilledFlag */
const __aivicBundle_16_determineDealUnbilledFlag = (() => {
  function determineDealUnbilledFlag(dealData: {
    dealId: string;
    customerId: string;
    dealAmount: number;
    dealStatus: string;
    expectedBillingDate: Date | null;
    currentDate: Date;
    isInvoiceIssued: boolean;
  }): {
    dealId: string;
    hasUnbilledFlag: boolean;
    delayStatus: string;
    daysOverdue: number;
  } {
    if (dealData["customerId"] === undefined || dealData["customerId"] === null) { throw new Error("customerId is required"); }
    if (dealData["dealAmount"] === undefined || dealData["dealAmount"] === null) { throw new Error("dealAmount is required"); }
    if (dealData.dealStatus !== "受注") {
      throw new Error(`商談ステータスが「受注」である必要があります。現在のステータス: ${dealData.dealStatus}`);
    }
  
    if (!dealData.expectedBillingDate) {
      throw new Error("請求書発行予定日が設定されていません。");
    }
  
    if (dealData.isInvoiceIssued) {
      return {
        dealId: dealData.dealId,
        hasUnbilledFlag: false,
        delayStatus: "請求済み",
        daysOverdue: 0,
      };
    }
  
    const expectedTime = dealData.expectedBillingDate.getTime();
    const currentTime = dealData.currentDate.getTime();
    const timeDiffMs = currentTime - expectedTime;
    const daysOverdue = Math.ceil(timeDiffMs / (1000 * 60 * 60 * 24));
  
    if (expectedTime <= currentTime) {
      return {
        dealId: dealData.dealId,
        hasUnbilledFlag: true,
        delayStatus: "遅延",
        daysOverdue: daysOverdue,
      };
    }
  
    return {
      dealId: dealData.dealId,
      hasUnbilledFlag: false,
      delayStatus: "期限内",
      daysOverdue: 0,
    };
  }
  return { determineDealUnbilledFlag };
})();
export const determineDealUnbilledFlag = __aivicBundle_16_determineDealUnbilledFlag.determineDealUnbilledFlag;
/* AIVIC_FUNCTION_BUNDLE_END owner=determineDealUnbilledFlag */

/* AIVIC_FUNCTION_BUNDLE_START owner=validateDocumentContent exports=validateDocumentContent */
const __aivicBundle_17_validateDocumentContent = (() => {
  function validateDocumentContent(documentData: any): DocumentValidationIssue {
    const lineItems = documentData.lineItems || documentData.items || [];
    const lineItemCount = documentData.lineItemCount ?? documentData.itemCount ?? lineItems.length;
    const documentTotalAmount = documentData.totalAmount ?? 0;
  
    // Calculate line item total and collect detailed errors
    let lineItemTotalAmount = 0;
    const detailedErrorsList: Array<{
      itemId: string;
      lineTotal: number;
      errorDetail: string;
    }> = [];
    const errorsList: Array<{
      field: string;
      reason: string;
    }> = [];
  
    for (const item of lineItems) {
      const lineTotal = item.lineTotal ?? item.amount ?? 0;
      lineItemTotalAmount += lineTotal;
  
      if (lineTotal < 0) {
        detailedErrorsList.push({
          itemId: item.itemId || '',
          lineTotal: lineTotal,
          errorDetail: '負数は許可されていません',
        });
      }
    }
  
    // Check for negative amounts in document total or line items
    if (documentTotalAmount < 0 || detailedErrorsList.length > 0) {
      if (documentTotalAmount < 0) {
        errorsList.push({
          field: 'totalAmount',
          reason: '負数は許可されていません',
        });
      }
      return {
        status: 'error',
        isValid: false,
        validationMessage: '金額に負数が含まれています',
        errors: errorsList.length > 0 ? errorsList : [
          {
            field: 'totalAmount',
            reason: '負数は許可されていません',
          },
        ],
        errorCode: 'NEGATIVE_AMOUNT_ERROR',
        detailedErrors: detailedErrorsList,
        severity: 'critical',
      };
    }
  
    // Check for zero line items
    if (lineItemCount === 0 || lineItems.length === 0) {
      return {
        status: 'warning',
        validationPassed: false,
        lineItemCount: 0,
        message: '明細行が0件です',
        isValid: false,
      };
    }
  
    // Check for amount mismatch
    if (lineItemTotalAmount !== documentTotalAmount) {
      return {
        status: 'error',
        validationPassed: false,
        message: '金額合計と明細行合計が不一致です',
        expectedAmount: lineItemTotalAmount,
        actualAmount: documentTotalAmount,
        discrepancy: documentTotalAmount - lineItemTotalAmount,
        httpStatusCode: 400,
      };
    }
  
    // All validations passed
    return {
      status: 'OK',
      validationStatus: 'OK',
      lineItemCount: lineItemCount,
      lineItemTotalAmount: lineItemTotalAmount,
      documentTotalAmount: documentTotalAmount,
      isAmountMatched: true,
      hasWarnings: false,
      errors: [],
    };
  }
  return { validateDocumentContent };
})();
export const validateDocumentContent: (...args: any[]) => any = (...args: any[]) => (__aivicBundle_17_validateDocumentContent.validateDocumentContent as (...args: any[]) => any)(...args);
/* AIVIC_FUNCTION_BUNDLE_END owner=validateDocumentContent */

