const __aivicBundle_26_detectUnbilledAndDelayedDeals = (() => {
  function detectUnbilledAndDelayedDeals(
    dealData: any,
    referenceDate?: Date
  ): any {
    const deals = Array.isArray(dealData) ? dealData : [dealData];
    const today = referenceDate || new Date();
  
    const unbilledDeals: any[] = [];
    const delayedDeals: any[] = [];
    const matchedDeals: any[] = [];
  
    let totalUnbilledAmount = 0;
    let totalDelayedAmount = 0;
  
    for (const deal of deals) {
      // Normalize field names to handle both camelCase and snake_case
      const dealId = deal.dealId || deal.deal_id;
      const customerId = deal.customerId || deal.customer_id;
      const customerName = deal.customerName || deal.customer_name;
      const dealAmount = deal.dealAmount || deal.deal_amount;
      const status = deal.status || deal.dealStatus || deal.deal_status;
  
      // Handle both estimatedRevenueDate/expectedBillingDate and billing_scheduled_date
      const expectedBillingDate =
        deal.estimatedRevenueDate ||
        deal.expectedBillingDate ||
        deal.billing_scheduled_date;
  
      // Handle both invoiceIssuedDate/actualBillingDate and billing_issued_date
      const actualBillingDate =
        deal.invoiceIssuedDate ||
        deal.actualBillingDate ||
        deal.billing_issued_date;
  
      // Only process deals with status "受注" (won/contract)
      if (status !== "受注" && status !== "contract" && status !== "won") {
        continue;
      }
  
      // Skip if no expected billing date
      if (!expectedBillingDate) {
        continue;
      }
  
      const expectedDate = new Date(expectedBillingDate);
  
      // Case 1: No invoice issued (unbilled)
      if (actualBillingDate === null || actualBillingDate === undefined) {
        const daysOverdue = Math.floor(
          (today.getTime() - expectedDate.getTime()) / (1000 * 60 * 60 * 24)
        );
  
        const unbilledDeal: any = {
          dealId,
          customerId,
          dealAmount,
          is_delayed: false,
        };
  
        // Include optional fields if present in input
        if (deal.status) unbilledDeal.status = deal.status;
        if (deal.dealStatus) unbilledDeal.dealStatus = deal.dealStatus;
        if (deal.estimatedRevenueDate)
          unbilledDeal.estimatedRevenueDate = deal.estimatedRevenueDate;
        if (deal.expectedBillingDate)
          unbilledDeal.expectedBillingDate = deal.expectedBillingDate;
        if (deal.billing_scheduled_date)
          unbilledDeal.billing_scheduled_date = deal.billing_scheduled_date;
        if (customerName) unbilledDeal.customerName = customerName;
        if (customerName) unbilledDeal.customer_name = customerName;
        unbilledDeal.invoiceIssuedDate = null;
        unbilledDeal.actualBillingDate = null;
        unbilledDeal.deal_id = dealId;
        unbilledDeal.deal_amount = dealAmount;
        unbilledDeal.customer_id = customerId;
        unbilledDeal.billing_scheduled_date = expectedBillingDate;
        unbilledDeal.billing_issued_date = null;
        unbilledDeal.daysOverdue = daysOverdue;
  
        unbilledDeals.push(unbilledDeal);
        totalUnbilledAmount += dealAmount;
      } else {
        // Case 2: Invoice issued - check if delayed
        const actualDate = new Date(actualBillingDate);
        const delayDays = Math.floor(
          (actualDate.getTime() - expectedDate.getTime()) / (1000 * 60 * 60 * 24)
        );
  
        // Default threshold is 0 days (any delay is considered delayed)
        const delayThreshold = 0;
  
        if (delayDays > delayThreshold) {
          const delayedDeal: any = {
            dealId,
            customerId,
            dealAmount,
            delayDays,
            is_delayed: true,
          };
  
          // Include optional fields if present in input
          if (deal.status) delayedDeal.status = deal.status;
          if (deal.dealStatus) delayedDeal.dealStatus = deal.dealStatus;
          if (deal.estimatedRevenueDate)
            delayedDeal.estimatedRevenueDate = deal.estimatedRevenueDate;
          if (deal.expectedBillingDate)
            delayedDeal.expectedBillingDate = deal.expectedBillingDate;
          if (deal.billing_scheduled_date)
            delayedDeal.billing_scheduled_date = deal.billing_scheduled_date;
          if (deal.invoiceIssuedDate)
            delayedDeal.invoiceIssuedDate = deal.invoiceIssuedDate;
          if (deal.actualBillingDate)
            delayedDeal.actualBillingDate = deal.actualBillingDate;
          if (customerName) delayedDeal.customerName = customerName;
          if (customerName) delayedDeal.customer_name = customerName;
          delayedDeal.deal_id = dealId;
          delayedDeal.deal_amount = dealAmount;
          delayedDeal.customer_id = customerId;
          delayedDeal.billing_scheduled_date = expectedBillingDate;
          delayedDeal.billing_issued_date = actualBillingDate;
  
          delayedDeals.push(delayedDeal);
          totalDelayedAmount += dealAmount;
        } else {
          // Matched: invoice issued on time
          const matchedDeal: any = {
            dealId,
            customerId,
            dealAmount,
          };
  
          if (deal.status) matchedDeal.status = deal.status;
          if (deal.dealStatus) matchedDeal.dealStatus = deal.dealStatus;
          if (deal.estimatedRevenueDate)
            matchedDeal.estimatedRevenueDate = deal.estimatedRevenueDate;
          if (deal.expectedBillingDate)
            matchedDeal.expectedBillingDate = deal.expectedBillingDate;
          if (deal.invoiceIssuedDate)
            matchedDeal.invoiceIssuedDate = deal.invoiceIssuedDate;
          if (deal.actualBillingDate)
            matchedDeal.actualBillingDate = deal.actualBillingDate;
  
          matchedDeals.push(matchedDeal);
        }
      }
    }
  
    const result: any = {
      unbilledDeals,
      delayedDeals,
      matchedDeals,
    };
  
    // Add snake_case variants for test compatibility
    result.unbilled_deals = unbilledDeals;
    result.delayed_deals = delayedDeals;
  
    if (totalUnbilledAmount > 0) {
      result.totalUnbilledAmount = totalUnbilledAmount;
    }
  
    if (totalDelayedAmount > 0) {
      result.totalDelayedAmount = totalDelayedAmount;
    }
  
    result.detectionTimestamp = new Date();
  
    return result;
  }
  return { detectUnbilledAndDelayedDeals };
})();
