/* AIVIC_FUNCTION_BUNDLE_START owner=detectDelayedBillingCases exports=detectDelayedBillingCases */
const __aivicBundle_27_detectDelayedBillingCases = (() => {
  function detectDelayedBillingCases(input: {
    deal_id: string;
    customer_id: string;
    status: string;
    revenue_recognition_date: Date;
    billing_issue_date: Date;
    deal_amount: number;
  }): {
    is_delayed: boolean;
    delay_days: number;
    delay_flag: string;
    deal_id: string;
    customer_id: string;
    status: string;
    deal_amount: number;
  } {
    const revenueDate = new Date(input.revenue_recognition_date);
    const billingDate = new Date(input.billing_issue_date);
  
    const timeDiffMs = billingDate.getTime() - revenueDate.getTime();
    const delayDays = Math.ceil(timeDiffMs / (1000 * 60 * 60 * 24));
  
    const isDelayed = delayDays >= 30;
    const delayFlag = isDelayed ? "ON" : "OFF";
  
    return {
      is_delayed: isDelayed,
      delay_days: delayDays,
      delay_flag: delayFlag,
      deal_id: input.deal_id,
      customer_id: input.customer_id,
      status: input.status,
      deal_amount: input.deal_amount,
    };
  }
  return { detectDelayedBillingCases };
})();
