/* AIVIC_FUNCTION_BUNDLE_START owner=detectRevenueRecognitionDateDiscrepancies exports=detectRevenueRecognitionDateDiscrepancies */
const __aivicBundle_28_detectRevenueRecognitionDateDiscrepancies = (() => {
  function detectRevenueRecognitionDateDiscrepancies(
    deals: Array<{
      dealId: string;
      status: string;
      revenueRecognitionDate: Date;
      invoiceIssuedDate: Date;
    }>
  ): {
    excludedDeals: Array<{
      dealId: string;
      status: string;
      reason: string;
    }>;
    processedDeals: Array<{
      dealId: string;
      status: string;
      hasDiscrepancy?: boolean;
      discrepancyDays?: number;
    }>;
    processingLog: string;
    excludedCount: number;
    processedCount: number;
  } {
    const excludedDeals: Array<{
      dealId: string;
      status: string;
      reason: string;
    }> = [];
    const processedDeals: Array<{
      dealId: string;
      status: string;
      hasDiscrepancy?: boolean;
      discrepancyDays?: number;
    }> = [];
    const logEntries: string[] = [];
  
    for (const deal of deals) {
      if (deal.status !== "受注") {
        excludedDeals.push({
          dealId: deal.dealId,
          status: deal.status,
          reason: "ステータス：受注以外のため除外",
        });
        logEntries.push(
          `[除外] dealId: ${deal.dealId}, status: ${deal.status} - ステータス：受注以外のため除外`
        );
      } else {
        const revenueDate = new Date(deal.revenueRecognitionDate);
        const invoiceDate = new Date(deal.invoiceIssuedDate);
        const timeDiffMs = revenueDate.getTime() - invoiceDate.getTime();
        const discrepancyDays = Math.ceil(timeDiffMs / (1000 * 60 * 60 * 24));
        const hasDiscrepancy = discrepancyDays !== 0;
  
        processedDeals.push({
          dealId: deal.dealId,
          status: deal.status,
          hasDiscrepancy,
          discrepancyDays: Math.abs(discrepancyDays),
        });
  
        if (hasDiscrepancy) {
          logEntries.push(
            `[処理] dealId: ${deal.dealId}, status: ${deal.status} - ズレ検出: ${Math.abs(discrepancyDays)}日`
          );
        } else {
          logEntries.push(
            `[処理] dealId: ${deal.dealId}, status: ${deal.status} - ズレなし`
          );
        }
      }
    }
  
    const processingLog = logEntries.join("\n");
  
    return {
      excludedDeals,
      processedDeals,
      processingLog,
      excludedCount: excludedDeals.length,
      processedCount: processedDeals.length,
    };
  }
  return { detectRevenueRecognitionDateDiscrepancies };
})();
export const detectRevenueRecognitionDateDiscrepancies = __aivicBundle_28_detectRevenueRecognitionDateDiscrepancies.detectRevenueRecognitionDateDiscrepancies;
