/* AIVIC_FUNCTION_BUNDLE_START owner=detectRevenueRecognitionDateDiscrepancy exports=detectRevenueRecognitionDateDiscrepancy */
const __aivicBundle_29_detectRevenueRecognitionDateDiscrepancy = (() => {
  function detectRevenueRecognitionDateDiscrepancy(input: {
    revenueRecognitionDate: Date;
    invoiceIssuanceDate: Date;
    toleranceDays: number;
  }): {
    isDiscrepancyDetected: boolean;
    discrepancyDays: number;
    alertMessage: string;
  } {
    const { revenueRecognitionDate, invoiceIssuanceDate, toleranceDays } = input;
  
    const timeDiffMs = Math.abs(
      invoiceIssuanceDate.getTime() - revenueRecognitionDate.getTime()
    );
    const discrepancyDays = Math.ceil(timeDiffMs / (1000 * 60 * 60 * 24));
  
    const isDiscrepancyDetected = discrepancyDays > toleranceDays;
  
    let alertMessage = '';
    if (isDiscrepancyDetected) {
      alertMessage = `売上計上予定日と請求発行日のズレが許容範囲を超えています。ズレ日数: ${discrepancyDays}日（許容: ${toleranceDays}日）。請求処理の遅延が発生しています。`;
    }
  
    return {
      isDiscrepancyDetected,
      discrepancyDays,
      alertMessage,
    };
  }
  return { detectRevenueRecognitionDateDiscrepancy };
})();
