/* AIVIC_FUNCTION_BUNDLE_START owner=determineBillingType exports=determineBillingType */
const __aivicBundle_36_determineBillingType = (() => {
  function determineBillingType(dealData: {
    dealId: string;
    dealStatus: string;
    billingTypeMonthly: boolean;
    billingTypeAfterDelivery: boolean;
    monthlyBillingPriority: number;
    afterDeliveryBillingPriority: number;
    expectedBillingDate: string;
    deliveryDate: string;
  }): string {
    if (dealData["dealId"] === undefined || dealData["dealId"] === null) { throw new Error("dealId is required"); }
    if (dealData["dealStatus"] === undefined || dealData["dealStatus"] === null) { throw new Error("dealStatus is required"); }
    if (dealData["expectedBillingDate"] === undefined || dealData["expectedBillingDate"] === null) { throw new Error("expectedBillingDate is required"); }
    if (dealData["deliveryDate"] === undefined || dealData["deliveryDate"] === null) { throw new Error("deliveryDate is required"); }
    const { billingTypeMonthly, billingTypeAfterDelivery, monthlyBillingPriority, afterDeliveryBillingPriority } = dealData;
  
    // 両方に該当する場合は優先度の低い方（数値が小さい方）を選択
    if (billingTypeMonthly && billingTypeAfterDelivery) {
      if (monthlyBillingPriority < afterDeliveryBillingPriority) {
        return 'monthly';
      } else {
        return 'afterDelivery';
      }
    }
  
    // 月次のみに該当
    if (billingTypeMonthly) {
      return 'monthly';
    }
  
    // 納期後のみに該当
    if (billingTypeAfterDelivery) {
      return 'afterDelivery';
    }
  
    // どちらにも該当しない場合は空文字列を返す
    return '';
  }
  return { determineBillingType };
})();
