/* AIVIC_FUNCTION_BUNDLE_START owner=validateAndApproveInvoice exports=validateAndApproveInvoice */
const __aivicBundle_37_validateAndApproveInvoice = (() => {
  function validateAndApproveInvoice(invoiceInput: {
    invoice_id: string;
    amount_total: number;
    currency: string;
    customer_info: {
      customer_id: string;
      customer_name: string;
      customer_address: string;
    };
    line_items: Array<{
      item_id: string;
      item_name: string;
      quantity: number;
      unit_price: number;
      line_amount: number;
    }>;
    issue_date: string;
    due_date: string;
    tax_rate: number;
    tax_amount: number;
  }): ApprovalResult {
    if (invoiceInput["invoice_id"] === undefined || invoiceInput["invoice_id"] === null) { throw new Error("invoice_id is required"); }
    if (invoiceInput["currency"] === undefined || invoiceInput["currency"] === null) { throw new Error("currency is required"); }
    if (invoiceInput["issue_date"] === undefined || invoiceInput["issue_date"] === null) { throw new Error("issue_date is required"); }
    if (invoiceInput["due_date"] === undefined || invoiceInput["due_date"] === null) { throw new Error("due_date is required"); }
    if (invoiceInput["tax_rate"] === undefined || invoiceInput["tax_rate"] === null) { throw new Error("tax_rate is required"); }
    const validationErrors: string[] = [];
    let customerInfoValid = true;
    let lineItemsValid = true;
    let amountRecognized = invoiceInput.amount_total;
  
    // Validate customer information completeness
    if (
      !invoiceInput.customer_info.customer_id ||
      !invoiceInput.customer_info.customer_name ||
      !invoiceInput.customer_info.customer_address
    ) {
      customerInfoValid = false;
      validationErrors.push(
        "顧客情報が不完全です。営業に確認を依頼してください"
      );
    }
  
    // Validate line items
    if (invoiceInput.line_items.length === 0) {
      lineItemsValid = false;
      validationErrors.push("請求明細が空です。営業に確認を依頼してください");
    }
  
    // Validate line item amounts match calculation
    let calculatedSubtotal = 0;
    for (const item of invoiceInput.line_items) {
      const expectedLineAmount = item.quantity * item.unit_price;
      if (Math.abs(item.line_amount - expectedLineAmount) > 0.01) {
        lineItemsValid = false;
        validationErrors.push(
          `明細行 ${item.item_id} の金額が計算と不一致です`
        );
      }
      calculatedSubtotal += item.line_amount;
    }
  
    // Validate total amount matches subtotal + tax
    const expectedTotal = calculatedSubtotal + invoiceInput.tax_amount;
    if (Math.abs(invoiceInput.amount_total - expectedTotal) > 0.01) {
      validationErrors.push("請求金額が商談金額と不一致です。差戻します");
    }
  
    // Determine approval status
    let approvalStatus = "approved";
    let approvalCompleted = true;
    let validationStatus = "OK";
  
    if (validationErrors.length > 0) {
      approvalStatus = "rejected";
      approvalCompleted = false;
      validationStatus = "ERROR";
    }
  
    const result: ApprovalResult = {
      approvalStatus: approvalStatus,
      invoiceReadyForCustomerPortal: approvalStatus === "approved",
      accountingEntryAllowed: approvalStatus === "approved",
      validationErrors: validationErrors,
      approvalTimestamp: new Date().toISOString(),
      approverComment: null,
      validation_status: validationStatus,
      amount_recognized: amountRecognized,
      customer_info_valid: customerInfoValid,
      line_items_valid: lineItemsValid,
      line_items_count: invoiceInput.line_items.length,
      approval_completed: approvalCompleted,
      message:
        validationStatus === "OK"
          ? "請求書の検証・承認が正常に完了しました"
          : undefined,
    };
  
    return result;
  }
  return { validateAndApproveInvoice };
})();
