const __aivicBundle_38_validateInvoiceAgainstCustomerInfo = (() => {
  async function validateInvoiceAgainstCustomerInfo(validationRequest: {
    invoiceId: string;
    customerId: string;
    invoiceAmount: number;
    expectedAmount: number;
    tolerance: number;
  }): Promise<{
    invoiceId: string;
    customerId: string;
    calculatedAmount: number;
    reportedAmount: number;
    amountDifference: number;
    validationStatus: string;
    invoiceStatus: string;
    returnReason: string;
    returnReasonDetail: string;
    notificationSent: boolean;
    notificationType: string;
    notificationMessage: string;
    auditLog: Array<{
      action: string;
      reason: string;
      timestamp: string;
    }>;
    discrepancyDetails: {
      expectedAmount: number;
      actualAmount: number;
      difference: number;
      toleranceLimit: number;
      isWithinTolerance: boolean;
    };
  }> {
    const {
      invoiceId,
      customerId,
      invoiceAmount,
      expectedAmount,
      tolerance,
    } = validationRequest;
  
    const calculatedAmount = expectedAmount;
    const reportedAmount = invoiceAmount;
    const amountDifference = Math.abs(invoiceAmount - expectedAmount);
    const isWithinTolerance = amountDifference <= tolerance;
  
    const auditLogEntry = {
      action: 'INVOICE_RETURNED',
      reason: 'AMOUNT_MISMATCH',
      timestamp: new Date().toISOString(),
    };
  
    const auditLog: Array<{
      action: string;
      reason: string;
      timestamp: string;
    }> = [];
  
    let validationStatus = 'APPROVED';
    let invoiceStatus = 'APPROVED';
    let returnReason = '';
    let returnReasonDetail = '';
    let notificationSent = false;
    let notificationType = '';
    let notificationMessage = '';
  
    if (!isWithinTolerance) {
      validationStatus = 'RETURNED';
      invoiceStatus = 'AWAITING_RESUBMISSION';
      returnReason = 'AMOUNT_MISMATCH';
      returnReasonDetail = '金額不一致';
      notificationSent = true;
      notificationType = 'INVOICE_RETURNED';
      notificationMessage = `請求書が返送されました。理由：${returnReasonDetail}`;
      auditLog.push(auditLogEntry);
    }
  
    const discrepancyDetails = {
      expectedAmount: calculatedAmount,
      actualAmount: reportedAmount,
      difference: amountDifference,
      toleranceLimit: tolerance,
      isWithinTolerance,
    };
  
    return {
      invoiceId,
      customerId,
      calculatedAmount,
      reportedAmount,
      amountDifference,
      validationStatus,
      invoiceStatus,
      returnReason,
      returnReasonDetail,
      notificationSent,
      notificationType,
      notificationMessage,
      auditLog,
      discrepancyDetails,
    };
  }
  return { validateInvoiceAgainstCustomerInfo };
})();
export const validateInvoiceAgainstCustomerInfo = __aivicBundle_38_validateInvoiceAgainstCustomerInfo.validateInvoiceAgainstCustomerInfo;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateInvoiceAgainstCustomerInfo */

