const __aivicBundle_39_validateInvoiceDocument = (() => {
  function validateInvoiceDocument(invoiceData: {
    invoiceId: string;
    invoiceDate: string;
    billingFrom: string;
    billingTo: string;
    totalAmount: number;
    taxAmount: number;
    subtotalAmount: number;
    lineItems: Array<{
      lineItemId: string;
      productName: string;
      quantity: number;
      unitPrice: number;
      lineAmount: number;
    }>;
    lineItemCount: number;
    status: string;
  }): ValidationResult {
    if (invoiceData["lineItemCount"] === undefined || invoiceData["lineItemCount"] === null) { throw new Error("lineItemCount is required"); }
    if (invoiceData["invoiceId"] === undefined || invoiceData["invoiceId"] === null) { throw new Error("invoiceId is required"); }
    if (invoiceData["invoiceDate"] === undefined || invoiceData["invoiceDate"] === null) { throw new Error("invoiceDate is required"); }
    if (invoiceData["billingFrom"] === undefined || invoiceData["billingFrom"] === null) { throw new Error("billingFrom is required"); }
    if (invoiceData["billingTo"] === undefined || invoiceData["billingTo"] === null) { throw new Error("billingTo is required"); }
    if (invoiceData["status"] === undefined || invoiceData["status"] === null) { throw new Error("status is required"); }
    const errorMessages: string[] = [];
    const warningMessages: string[] = [];
  
    // 明細行が存在するかチェック
    if (!invoiceData.lineItems || invoiceData.lineItems.length === 0) {
      warningMessages.push("明細行が1行以上必要です");
    }
  
    // 明細行数の一致確認
    const actualLineItemCount = invoiceData.lineItems?.length ?? 0;
    
  
    // 明細行の合計金額を計算
    let calculatedLineItemTotal = 0;
    if (invoiceData.lineItems && invoiceData.lineItems.length > 0) {
      calculatedLineItemTotal = invoiceData.lineItems.reduce(
        (sum, item) => sum + (item.lineAmount ?? 0),
        0
      );
    }
  
    // 小計と明細行合計の一致確認
    const subtotalMatch =
      invoiceData.subtotalAmount === calculatedLineItemTotal;
    if (!subtotalMatch && calculatedLineItemTotal > 0) {
      errorMessages.push(
        `小計が一致しません。期待値: ${calculatedLineItemTotal}, 実際: ${invoiceData.subtotalAmount}`
      );
    }
  
    // 合計金額の計算（小計 + 税金）
    const expectedTotalAmount =
      invoiceData.subtotalAmount + invoiceData.taxAmount;
    const totalAmountMatch = invoiceData.totalAmount === expectedTotalAmount;
  
    if (!totalAmountMatch) {
      errorMessages.push(
        `合計金額が一致しません。期待値: ${expectedTotalAmount}, 実際: ${invoiceData.totalAmount}`
      );
    }
  
    // 金額が負数でないかチェック
    if (invoiceData.totalAmount < 0) {
      errorMessages.push("合計金額が負数です");
    }
    if (invoiceData.taxAmount < 0) {
      errorMessages.push("税金が負数です");
    }
    if (invoiceData.subtotalAmount < 0) {
      errorMessages.push("小計が負数です");
    }
  
    // 明細行の金額チェック
    if (invoiceData.lineItems) {
      for (const item of invoiceData.lineItems) {
        if (item.quantity < 0) {
          errorMessages.push(
            `明細行 ${item.lineItemId} の数量が負数です`
          );
        }
        if (item.unitPrice < 0) {
          errorMessages.push(
            `明細行 ${item.lineItemId} の単価が負数です`
          );
        }
        if (item.lineAmount < 0) {
          errorMessages.push(
            `明細行 ${item.lineItemId} の金額が負数です`
          );
        }
        // 行金額の計算確認
        const expectedLineAmount = item.quantity * item.unitPrice;
        if (item.lineAmount !== expectedLineAmount) {
          errorMessages.push(
            `明細行 ${item.lineItemId} の金額計算が一致しません。期待値: ${expectedLineAmount}, 実際: ${item.lineAmount}`
          );
        }
      }
    }
  
    // 検証ステータスの決定
    let validationStatus: string;
    let isValid: boolean;
  
    if (errorMessages.length > 0) {
      validationStatus = "ERROR";
      isValid = false;
    } else if (warningMessages.length > 0) {
      validationStatus = "WARNING";
      isValid = false;
    } else {
      validationStatus = "OK";
      isValid = true;
    }
  
    const result: ValidationResult = {
      isValid,
      status: validationStatus,
      errorMessages,
      warningMessages,
      lineItemCount: actualLineItemCount,
      totalAmountMatch,
      validationStatus,
    };
  
    return result;
  }
  return { validateInvoiceDocument };
})();
