/* AIVIC_FUNCTION_BUNDLE_START owner=validateInvoiceDataBeforeDistribution exports=validateInvoiceDataBeforeDistribution */
const __aivicBundle_42_validateInvoiceDataBeforeDistribution = (() => {
  function validateInvoiceDataBeforeDistribution(invoiceData: {
    invoiceId: string;
    customerId: string;
    totalAmount: number;
    lineItems: Array<{
      itemId?: string;
      description: string;
      quantity: number;
      unitPrice: number;
      amount?: number;
    }>;
    approvalStatus?: string;
    distributionStatus?: string;
    validationCompleted?: boolean;
  }): {
    isReadyForDistribution: boolean;
    validationErrors: string[];
    warnings: string[];
    readinessScore: number;
  } {
    const validationErrors: string[] = [];
    const warnings: string[] = [];
    let readinessScore = 100;
  
    // 妥当性確認完了チェック
    if (invoiceData.validationCompleted === false) {
      throw new Error('請求書の妥当性確認が完了していません');
    }
  
    // 承認ステータスチェック
    if (invoiceData.approvalStatus !== 'approved') {
      validationErrors.push('承認ステータスが「approved」ではありません');
      readinessScore -= 30;
    }
  
    // 金額チェック
    if (invoiceData.totalAmount <= 0) {
      validationErrors.push('金額が0円です');
      readinessScore -= 30;
    }
  
    // 明細行チェック
    if (!invoiceData.lineItems || invoiceData.lineItems.length === 0) {
      validationErrors.push('明細行がありません');
      readinessScore -= 30;
    } else {
      // 明細の金額妥当性チェック
      let calculatedTotal = 0;
      for (const item of invoiceData.lineItems) {
        const lineTotal = item.quantity * item.unitPrice;
        calculatedTotal += lineTotal;
  
        if (item.quantity <= 0) {
          validationErrors.push(`明細「${item.description}」の数量が不正です`);
          readinessScore -= 10;
        }
  
        if (item.unitPrice < 0) {
          validationErrors.push(`明細「${item.description}」の単価が負数です`);
          readinessScore -= 10;
        }
      }
  
      // 合計金額と明細の整合性チェック
      if (Math.abs(calculatedTotal - invoiceData.totalAmount) > 1) {
        warnings.push('合計金額と明細の合計が一致しません');
        readinessScore -= 10;
      }
    }
  
    // 顧客IDチェック
    if (!invoiceData.customerId || invoiceData.customerId.trim() === '') {
      validationErrors.push('顧客IDが指定されていません');
      readinessScore -= 20;
    }
  
    // 請求書IDチェック
    if (!invoiceData.invoiceId || invoiceData.invoiceId.trim() === '') {
      validationErrors.push('請求書IDが指定されていません');
      readinessScore -= 20;
    }
  
    // 配信ステータスチェック
    if (invoiceData.distributionStatus && invoiceData.distributionStatus !== '未配信' && invoiceData.distributionStatus !== 'pending') {
      warnings.push('配信ステータスが「未配信」ではありません');
      readinessScore -= 5;
    }
  
    // readinessScore を 0-100 の範囲に正規化
    readinessScore = Math.max(0, Math.min(100, readinessScore));
  
    const isReadyForDistribution = validationErrors.length === 0 && readinessScore === 100;
  
    return {
      isReadyForDistribution,
      validationErrors,
      warnings,
      readinessScore,
    };
  }
  return { validateInvoiceDataBeforeDistribution };
})();
export const validateInvoiceDataBeforeDistribution = __aivicBundle_42_validateInvoiceDataBeforeDistribution.validateInvoiceDataBeforeDistribution;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateInvoiceDataBeforeDistribution */

